// ============================================================================
// GbE_DMA_apb: APB4 register wrapper around GbE_DMA_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/GbE_DMA.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/GbE_DMA.md
// ============================================================================
module GbE_DMA_apb #(
  parameter logic [3:0] AXI_ID = 4'd10,
  parameter int TXF_BYTES = 2048,
  parameter int RXF_BYTES = 4096
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic [7:0] gtxd,
  output logic gtx_en,
  output logic gtx_er,
  input logic [7:0] grxd,
  input logic grx_dv,
  input logic grx_er,
  output logic [3:0] m_awid,
  output logic [31:0] m_awaddr,
  output logic [7:0] m_awlen,
  output logic [2:0] m_awsize,
  output logic [1:0] m_awburst,
  output logic [2:0] m_awprot,
  output logic m_awvalid,
  input logic m_awready,
  output logic [31:0] m_wdata,
  output logic [3:0] m_wstrb,
  output logic m_wlast,
  output logic m_wvalid,
  input logic m_wready,
  input logic [3:0] m_bid,
  input logic [1:0] m_bresp,
  input logic m_bvalid,
  output logic m_bready,
  output logic [3:0] m_arid,
  output logic [31:0] m_araddr,
  output logic [7:0] m_arlen,
  output logic [2:0] m_arsize,
  output logic [1:0] m_arburst,
  output logic [2:0] m_arprot,
  output logic m_arvalid,
  input logic m_arready,
  input logic [3:0] m_rid,
  input logic [31:0] m_rdata,
  input logic [1:0] m_rresp,
  input logic m_rlast,
  input logic m_rvalid,
  output logic m_rready
);
  localparam logic [31:0] ID_VALUE = 32'h5C410100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [18:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd19) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [4:0]    c_cfg_div;
  logic [47:0]   c_cfg_mac;
  logic          c_cfg_promisc;
  logic          c_cfg_pause_en;
  logic          c_tx_en;
  logic          c_rx_en;
  logic [31:0]   c_tx_base;
  logic [15:0]   c_tx_num;
  logic [15:0]   c_tx_tail;
  logic [15:0]   c_tx_head;
  logic [31:0]   c_rx_base;
  logic [15:0]   c_rx_num;
  logic [15:0]   c_rx_tail;
  logic [15:0]   c_rx_head;
  logic          c_clr_err;
  logic          c_err;
  logic          c_tx_paused;
  logic [15:0]   c_tx_frames;
  logic [15:0]   c_rx_frames;
  logic [15:0]   c_rx_drop;
  logic          c_tx_irq;
  logic          c_rx_irq;
  logic          c_drop_irq;
  logic          c_err_irq;
  GbE_DMA_top #(.AXI_ID(AXI_ID), .TXF_BYTES(TXF_BYTES), .RXF_BYTES(RXF_BYTES)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cfg_div(c_cfg_div),
    .cfg_mac(c_cfg_mac),
    .cfg_promisc(c_cfg_promisc),
    .cfg_pause_en(c_cfg_pause_en),
    .gtxd(gtxd),
    .gtx_en(gtx_en),
    .gtx_er(gtx_er),
    .grxd(grxd),
    .grx_dv(grx_dv),
    .grx_er(grx_er),
    .tx_en(c_tx_en),
    .rx_en(c_rx_en),
    .tx_base(c_tx_base),
    .tx_num(c_tx_num),
    .tx_tail(c_tx_tail),
    .tx_head(c_tx_head),
    .rx_base(c_rx_base),
    .rx_num(c_rx_num),
    .rx_tail(c_rx_tail),
    .rx_head(c_rx_head),
    .clr_err(c_clr_err),
    .err(c_err),
    .tx_paused(c_tx_paused),
    .tx_frames(c_tx_frames),
    .rx_frames(c_rx_frames),
    .rx_drop(c_rx_drop),
    .tx_irq(c_tx_irq),
    .rx_irq(c_rx_irq),
    .drop_irq(c_drop_irq),
    .err_irq(c_err_irq),
    .m_awid(m_awid),
    .m_awaddr(m_awaddr),
    .m_awlen(m_awlen),
    .m_awsize(m_awsize),
    .m_awburst(m_awburst),
    .m_awprot(m_awprot),
    .m_awvalid(m_awvalid),
    .m_awready(m_awready),
    .m_wdata(m_wdata),
    .m_wstrb(m_wstrb),
    .m_wlast(m_wlast),
    .m_wvalid(m_wvalid),
    .m_wready(m_wready),
    .m_bid(m_bid),
    .m_bresp(m_bresp),
    .m_bvalid(m_bvalid),
    .m_bready(m_bready),
    .m_arid(m_arid),
    .m_araddr(m_araddr),
    .m_arlen(m_arlen),
    .m_arsize(m_arsize),
    .m_arburst(m_arburst),
    .m_arprot(m_arprot),
    .m_arvalid(m_arvalid),
    .m_arready(m_arready),
    .m_rid(m_rid),
    .m_rdata(m_rdata),
    .m_rresp(m_rresp),
    .m_rlast(m_rlast),
    .m_rvalid(m_rvalid),
    .m_rready(m_rready)
  );

  // ---------------- registers ----------------
  logic [3:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [8:0] r_CTRL;   // 12'h014 CTRL
  logic [31:0] r_MAC0;   // 12'h018 MAC0
  logic [15:0] r_MAC1;   // 12'h01C MAC1
  logic [31:0] r_TX_BASE;   // 12'h020 TX_BASE
  logic [15:0] r_TX_NUM;   // 12'h024 TX_NUM
  logic [15:0] r_TX_TAIL;   // 12'h028 TX_TAIL
  logic [31:0] r_RX_BASE;   // 12'h02C RX_BASE
  logic [15:0] r_RX_NUM;   // 12'h030 RX_NUM
  logic [15:0] r_RX_TAIL;   // 12'h034 RX_TAIL
  logic [0:0] p_CMD;   // 12'h038 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 9'h0;
      r_MAC0 <= 32'h0;
      r_MAC1 <= 16'h0;
      r_TX_BASE <= 32'h0;
      r_TX_NUM <= 16'h0;
      r_TX_TAIL <= 16'h0;
      r_RX_BASE <= 32'h0;
      r_RX_NUM <= 16'h0;
      r_RX_TAIL <= 16'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[3:0] & wmask[3:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[8:0]) | (PWDATA[8:0] & wmask[8:0]);
      if (wr && hit[6]) r_MAC0 <= (r_MAC0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_MAC1 <= (r_MAC1 & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[8]) r_TX_BASE <= (r_TX_BASE & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9]) r_TX_NUM <= (r_TX_NUM & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[10]) r_TX_TAIL <= (r_TX_TAIL & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[11]) r_RX_BASE <= (r_RX_BASE & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[12]) r_RX_NUM <= (r_RX_NUM & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[13]) r_RX_TAIL <= (r_RX_TAIL & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      p_CMD <= (wr && hit[14]) ? PWDATA[0:0] & wmask[0:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_tx_en = r_CTRL[0:0];
  assign c_rx_en = r_CTRL[1:1];
  assign c_cfg_promisc = r_CTRL[2:2];
  assign c_cfg_pause_en = r_CTRL[3:3];
  assign c_cfg_div = r_CTRL[8:4];
  assign c_cfg_mac[31:0] = r_MAC0[31:0];
  assign c_cfg_mac[47:32] = r_MAC1[15:0];
  assign c_tx_base = r_TX_BASE[31:0];
  assign c_tx_num = r_TX_NUM[15:0];
  assign c_tx_tail = r_TX_TAIL[15:0];
  assign c_rx_base = r_RX_BASE[31:0];
  assign c_rx_num = r_RX_NUM[15:0];
  assign c_rx_tail = r_RX_TAIL[15:0];
  assign c_clr_err = p_CMD;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_tx_irq;
    irq_set[1] = c_rx_irq;
    irq_set[2] = c_drop_irq;
    irq_set[3] = c_err_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(r_MAC0);
      10'd7: apb_rdata = 32'(r_MAC1);
      10'd8: apb_rdata = 32'(r_TX_BASE);
      10'd9: apb_rdata = 32'(r_TX_NUM);
      10'd10: apb_rdata = 32'(r_TX_TAIL);
      10'd11: apb_rdata = 32'(r_RX_BASE);
      10'd12: apb_rdata = 32'(r_RX_NUM);
      10'd13: apb_rdata = 32'(r_RX_TAIL);
      10'd15: apb_rdata = 32'({c_rx_head, c_tx_head});
      10'd16: apb_rdata = 32'({c_tx_paused, c_err});
      10'd17: apb_rdata = 32'({c_rx_frames, c_tx_frames});
      10'd18: apb_rdata = 32'({c_rx_drop});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
